// CC-BY

// sign function, but 0 retuns -1 instead of 0
vec2 sign2(vec2 x) {
    return -2.0 * step(x, vec2(0.0)) + 1.0;
}

vec2 hex(vec2 p) {
    float s = sqrt(3.0);

    // Squish on y-axis
    vec2 sp = p;
    sp.y /= s;

    // Rectangular cell
    vec2 rec_cell = floor(sp);

    // Points of interest
    vec2 center = rec_cell + vec2(0.5);
    vec2 center_to_sp = sp - center;
    vec2 center_to_corner = sign2(center_to_sp) * vec2(0.5);
    vec2 corner = center + center_to_corner;

    // Undo the squish
    center.y *= s;
    corner.y *= s;

    // Compare vectors
    vec2 center_to_p = center - p;
    vec2 corner_to_p = corner - p;
    if(dot(center_to_p, center_to_p) < dot(corner_to_p, corner_to_p))
        return center;

    else
        return corner;
}


int mod3(int n) {
    int m3 = n % 3;
    if (m3 < 0)
        m3 += 3;

    return m3;
}

int mod3_2(int n) {
    int s = sign(n);
    return (3 + s * ((s * n) % 3)) % 3;
}

// Method pointed out by spalmer
// Calculate hex ID on a scaled and skewed lattice
vec2 hex2(vec2 p) {
    vec2 scaled_skewed = vec2(p.x, 0.5 * (p.x + p.y * sqrt(3.0))) * 2.0;

    ivec2 rec_cell = ivec2(floor(scaled_skewed));
	vec2 rec_loc = fract(scaled_skewed);

	int m3 = mod3_2(rec_cell.x + rec_cell.y);

    ivec2 hex_id = rec_cell + m3;
    if (m3 == 2)
        if (rec_loc.x > rec_loc.y)
            hex_id -= ivec2(1, 2);
        else
            hex_id -= ivec2(2, 1);

    vec2 hex_id_f = vec2(hex_id);        

    return vec2(hex_id_f.x, sqrt(3.0) * (2.0 * hex_id_f.y - hex_id_f.x) / 3.0) / 2.0;
}

// https://www.shadertoy.com/view/4djSRW
// For color
vec3 hash32(vec2 p) {
	vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz+33.33);
    return fract((p3.xxy+p3.yzz)*p3.zyx);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float ar = iResolution.x / iResolution.y;
    float scale = 5.0;
    vec2 time_shift = -vec2(iTime);
    time_shift.x /= ar;

    // Nearest hexagon to the pixel
    vec2 uv = fragCoord / iResolution.xy;
    uv.x *= ar;
    vec2 p = scale * uv + time_shift;
    vec2 hex_center = hex2(p);

    // Nearest hexagon to the mouse
    vec2 mouse_uv = iMouse.xy / iResolution.xy;
    mouse_uv.x *= ar;
    vec2 mouse_p = scale * mouse_uv + time_shift;
    vec2 mouse_hex_center = hex2(mouse_p);

    // Assign a random color
    vec3 inverse_dist = sqrt(vec3(1.0 - 1.5 * length(hex_center - p)));
    vec3 hue = normalize(abs(hash32(hex_center)));
    vec3 color = inverse_dist * hue;

    // Highlight the clicked hexagon
    if (hex_center == mouse_hex_center && sign(iMouse.z) > 0.0) {
        color /= max(max(color.x, color.y), color.z);
    }

    fragColor = vec4(color, 1.0);
}
